// Times arrow::internal::CountSetBits (from the checked-out bitmap_ops.cc)
// and writes the counts for a fixed set of inputs so versions can be compared.
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <vector>
#include "arrow/util/bitmap_ops.h"

static int64_t Naive(const uint8_t* d, int64_t off, int64_t len) {
  int64_t c = 0;
  for (int64_t i = off; i < off + len; ++i) c += (d[i >> 3] >> (i & 7)) & 1;
  return c;
}

int main(int argc, char** argv) {
  const char* out = argc > 1 ? argv[1] : "out/counts.txt";
  std::vector<uint8_t> buf(1 << 17);
  uint64_t s = 0x9E3779B97F4A7C15ull;
  for (auto& b : buf) { s ^= s << 13; s ^= s >> 7; s ^= s << 17; b = uint8_t(s >> 24); }

  // correctness: many offsets/lengths vs naive, recorded to the output file
  FILE* f = fopen(out, "w");
  if (!f) return 2;
  int bad = 0;
  for (int64_t off : {0, 1, 3, 7, 8, 13, 63, 64, 65, 100})
    for (int64_t len : {0, 1, 7, 8, 63, 64, 65, 127, 128, 255, 256, 257, 511, 512, 1000, 1024, 4099, 100000, 1000000}) {
      if (off + len > int64_t(buf.size()) * 8) continue;
      int64_t c = arrow::internal::CountSetBits(buf.data(), off, len);
      if (c != Naive(buf.data(), off, len)) ++bad;
      fprintf(f, "%lld %lld %lld\n", (long long)off, (long long)len, (long long)c);
    }
  fclose(f);
  if (bad) { fprintf(stderr, "%d mismatches vs naive\n", bad); return 1; }

  // timing: the three sizes from the PR's benchmark, byte-aligned, many calls
  volatile int64_t sink = 0;
  auto t0 = std::chrono::steady_clock::now();
  for (int64_t nbytes : {int64_t(16), int64_t(1) << 10, int64_t(1) << 17}) {
    int64_t reps = (int64_t(1) << 29) / nbytes / 4;  // ~128 MiB per size
    for (int64_t i = 0; i < reps; ++i) {
      // vary length slightly so calls can't be hoisted
      sink = sink + arrow::internal::CountSetBits(buf.data(), 0, nbytes * 8 - (i & 1));
    }
  }
  double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
  printf("PERFPROOF {\"value\": %.9f}\n", secs);
  return 0;
}
EOF
